<?php

declare(strict_types=1);
require_once dirname(__DIR__,2).'/src/includes/errors.php'; require_once dirname(__DIR__,2).'/src/includes/app.php';
$idUsuario=stridebr_require_login(); stridebr_require_role('admin'); require_once dirname(__DIR__,2).'/src/config/pg_config.php'; require_once dirname(__DIR__,2).'/src/includes/admin.php';
$targetId=trim((string)($_GET['id']??$_POST['idusuario']??''));
$get=$pdo->prepare("SELECT idusuario,nomeusuario,nome_exibicao,username,emailusuario,papelusuario,statususuario,verificado,email_verificado_em,dataregistrousuario,ultimologin,ipultimologin,bloqueado_em,bloqueio_motivo,sessao_versao FROM usuarios WHERE idusuario=:id LIMIT 1"); $get->execute([':id'=>$targetId]); $target=$get->fetch(); if(!$target){http_response_code(404);exit('Usuário não encontrado.');}
$actorRole=stridebr_user_role(); $canManage=stridebr_admin_can_manage($actorRole,$idUsuario,$target,false); $canDelete=stridebr_admin_can_manage($actorRole,$idUsuario,$target,true); $errors=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 stridebr_verify_csrf();
 try{
  if(!$canManage && !$canDelete) throw new RuntimeException('Você não pode gerenciar esta conta.');
  $action=(string)($_POST['action']??'');
  if($action==='save' && $canManage){$nome=trim((string)$_POST['nomeusuario']);$display=trim((string)$_POST['nome_exibicao']);$username=stridebr_lower(trim((string)$_POST['username']));$email=stridebr_lower(trim((string)$_POST['emailusuario'])); if($nome===''||$display==='')throw new InvalidArgumentException('Nome inválido.'); if($username!==''&&!stridebr_username_is_valid($username))throw new InvalidArgumentException('Username inválido.'); if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new InvalidArgumentException('E-mail inválido.'); $check=$pdo->prepare("SELECT 1 FROM usuarios WHERE idusuario<>:id AND (lower(emailusuario)=lower(:email) OR (:username1<>'' AND lower(username)=lower(:username2))) LIMIT 1");$check->execute([':id'=>$targetId,':email'=>$email,':username1'=>$username,':username2'=>$username]);if($check->fetchColumn())throw new RuntimeException('E-mail ou username já está em uso.');$emailChanged=stridebr_lower($target['emailusuario'])!==$email;$upd=$pdo->prepare('UPDATE usuarios SET nomeusuario=:nome,nome_exibicao=:display,username=:username,emailusuario=:email,verificado=CASE WHEN :changed1 THEN FALSE ELSE verificado END,email_verificado_em=CASE WHEN :changed2 THEN NULL ELSE email_verificado_em END,sessao_versao=sessao_versao+1 WHERE idusuario=:id');$upd->bindValue(':nome',$nome);$upd->bindValue(':display',$display);$upd->bindValue(':username',$username!==''?$username:null,$username!==''?PDO::PARAM_STR:PDO::PARAM_NULL);$upd->bindValue(':email',$email);$upd->bindValue(':changed1',$emailChanged,PDO::PARAM_BOOL);$upd->bindValue(':changed2',$emailChanged,PDO::PARAM_BOOL);$upd->bindValue(':id',$targetId);$upd->execute();stridebr_admin_audit($pdo,$idUsuario,'user.edit','usuario',$targetId,['email_alterado'=>$emailChanged]);stridebr_flash('success','Usuário atualizado e sessões antigas invalidadas.');}
  elseif($action==='block'&&$canManage){$reason=trim((string)($_POST['motivo']??''));$stmt=$pdo->prepare("UPDATE usuarios SET statususuario='Desativado',bloqueado_em=NOW(),bloqueado_por=:ator,bloqueio_motivo=:motivo,sessao_versao=sessao_versao+1 WHERE idusuario=:id");$stmt->execute([':ator'=>$idUsuario,':motivo'=>$reason!==''?$reason:null,':id'=>$targetId]);stridebr_admin_audit($pdo,$idUsuario,'user.block','usuario',$targetId,['motivo'=>$reason]);stridebr_flash('success','Usuário bloqueado.');}
  elseif($action==='unblock'&&$canManage){$pdo->prepare("UPDATE usuarios SET statususuario='Ativo',bloqueado_em=NULL,bloqueado_por=NULL,bloqueio_motivo=NULL,sessao_versao=sessao_versao+1 WHERE idusuario=:id")->execute([':id'=>$targetId]);stridebr_admin_audit($pdo,$idUsuario,'user.unblock','usuario',$targetId);stridebr_flash('success','Usuário desbloqueado.');}
  elseif($action==='role'&&$actorRole==='owner'&&$canManage){$role=(string)($_POST['papelusuario']??'user');if(!in_array($role,['user','moderator','admin'],true))throw new InvalidArgumentException('Papel inválido.');$pdo->prepare('UPDATE usuarios SET papelusuario=:role,sessao_versao=sessao_versao+1 WHERE idusuario=:id')->execute([':role'=>$role,':id'=>$targetId]);stridebr_admin_audit($pdo,$idUsuario,'user.role.update','usuario',$targetId,['depois'=>$role]);stridebr_flash('success','Papel atualizado.');}
  elseif($action==='delete'&&$canDelete){if((string)($_POST['confirmacao']??'')!=='APAGAR')throw new RuntimeException('Digite APAGAR para confirmar.');stridebr_admin_audit($pdo,$idUsuario,'user.delete','usuario',$targetId,['email'=>$target['emailusuario']]);$pdo->prepare('DELETE FROM usuarios WHERE idusuario=:id')->execute([':id'=>$targetId]);stridebr_flash('success','Usuário apagado.');header('Location:/admin/users.php');exit;}
  else throw new InvalidArgumentException('Ação inválida ou sem permissão.');
  header('Location:/admin/user.php?id='.rawurlencode($targetId));exit;
 }catch(Throwable $e){$errors[]=$e instanceof RuntimeException||$e instanceof InvalidArgumentException?$e->getMessage():'Não foi possível executar a ação.';}
}
$get->execute([':id'=>$targetId]);$target=$get->fetch();$flashes=stridebr_take_flashes();
?>
<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><link rel="stylesheet" href="<?php echo stridebr_e(stridebr_asset('/assets/css/style.css'));?>"><title>Gerenciar usuário | StrideBR</title></head><body class="admin-body"><div class="container-fluid"><?php require dirname(__DIR__,2).'/src/layout/header.php';?><main class="main-content"><div class="admin-shell"><?php echo stridebr_admin_nav('users');?><div class="admin-heading"><div><a href="/admin/users.php">← Usuários</a><h1><?php echo stridebr_e($target['nome_exibicao']?:$target['nomeusuario']);?></h1><p><?php echo stridebr_e($target['emailusuario']);?> · <?php echo stridebr_e($target['papelusuario']);?></p></div><span class="status-pill <?php echo $target['statususuario']==='Ativo'?'is-ok':'is-blocked';?>"><?php echo stridebr_e($target['statususuario']);?></span></div><?php foreach($flashes as $f):?><div class="alert alert-<?php echo stridebr_e($f['type']);?>"><?php echo stridebr_e($f['message']);?></div><?php endforeach;?><?php foreach($errors as $e):?><div class="alert alert-danger"><?php echo stridebr_e($e);?></div><?php endforeach;?><?php if(!$canManage&&!$canDelete):?><div class="alert alert-info">Você pode visualizar esta conta, mas não alterá-la por causa da hierarquia administrativa.</div><?php endif;?><div class="admin-grid"><section class="admin-card"><h2>Conta</h2><form method="post" class="admin-user-form"><?php echo stridebr_csrf_field();?><input type="hidden" name="idusuario" value="<?php echo stridebr_e($targetId);?>"><input type="hidden" name="action" value="save"><label>Nome<input name="nomeusuario" maxlength="255" value="<?php echo stridebr_e($target['nomeusuario']);?>" <?php echo !$canManage?'disabled':'';?>></label><label>Nome de exibição<input name="nome_exibicao" maxlength="120" value="<?php echo stridebr_e($target['nome_exibicao']?:$target['nomeusuario']);?>" <?php echo !$canManage?'disabled':'';?>></label><label>@username<input name="username" maxlength="40" value="<?php echo stridebr_e($target['username']??'');?>" <?php echo !$canManage?'disabled':'';?>></label><label>E-mail<input type="email" name="emailusuario" value="<?php echo stridebr_e($target['emailusuario']);?>" <?php echo !$canManage?'disabled':'';?>></label><?php if($canManage):?><button class="primary-action">Salvar</button><?php endif;?></form></section><section class="admin-card"><h2>Segurança e acesso</h2><dl class="admin-definition"><div><dt>E-mail</dt><dd><?php echo $target['email_verificado_em']||stridebr_db_bool($target['verificado'])?'Verificado':'Não verificado';?></dd></div><div><dt>Último login</dt><dd><?php echo stridebr_e($target['ultimologin']??'—');?></dd></div><div><dt>IP recente</dt><dd><?php echo stridebr_e($target['ipultimologin']??'—');?></dd></div><div><dt>Conta criada</dt><dd><?php echo stridebr_e($target['dataregistrousuario']);?></dd></div></dl><?php if($canManage):?><?php if($target['statususuario']==='Ativo'):?><form method="post" class="admin-danger-form"><?php echo stridebr_csrf_field();?><input type="hidden" name="idusuario" value="<?php echo stridebr_e($targetId);?>"><input type="hidden" name="action" value="block"><label>Motivo do bloqueio<textarea name="motivo" rows="3" maxlength="1000"></textarea></label><button class="danger-action">Bloquear conta</button></form><?php else:?><p><?php echo stridebr_e($target['bloqueio_motivo']??'Sem motivo registrado.');?></p><form method="post"><?php echo stridebr_csrf_field();?><input type="hidden" name="idusuario" value="<?php echo stridebr_e($targetId);?>"><input type="hidden" name="action" value="unblock"><button class="primary-action">Desbloquear conta</button></form><?php endif;?><?php endif;?></section></div><?php if($actorRole==='owner'&&$canManage):?><section class="admin-card admin-table-card"><h2>Papel administrativo</h2><form method="post" class="admin-inline-form"><?php echo stridebr_csrf_field();?><input type="hidden" name="idusuario" value="<?php echo stridebr_e($targetId);?>"><input type="hidden" name="action" value="role"><select name="papelusuario"><?php foreach(['user','moderator','admin'] as $r):?><option value="<?php echo $r;?>"<?php echo $target['papelusuario']===$r?' selected':'';?>><?php echo $r;?></option><?php endforeach;?></select><button class="secondary-action">Alterar papel</button></form></section><?php endif;?><?php if($canDelete):?><section class="admin-card admin-table-card danger-zone"><h2>Apagar usuário</h2><p>Remove a conta e os dados associados pelas regras de cascata do banco. Esta ação não pode ser desfeita.</p><form method="post" class="admin-inline-form"><?php echo stridebr_csrf_field();?><input type="hidden" name="idusuario" value="<?php echo stridebr_e($targetId);?>"><input type="hidden" name="action" value="delete"><input name="confirmacao" placeholder="Digite APAGAR" autocomplete="off"><button class="danger-action">Apagar definitivamente</button></form></section><?php endif;?></div></main></div><?php require dirname(__DIR__,2).'/src/layout/footer.php';?></body></html>
